const user = $('Loops over users').first().json;
const newsItems = $('fetch news').all().map(item => item.json);
const allAds = $('fetch related ads').all().map(item => item.json);

// Split user topics
const userTopics = user.topics.toLowerCase().split(',').map(t => t.trim());

// Filter news by user topics
const filteredNews = newsItems.filter(item => 
  userTopics.includes(item.topic.toLowerCase().trim())
);

const isPremium = user.is_premium === true || user.is_premium === 'true';

// Clean all filtered news — let LLM decide which to pick
const cleanNews = filteredNews.map(item => ({
  title: item.title,
  link: item.link,
  summary: item.title,
  topic: item.topic
}));

// No ads for premium users
const defaultAd = {
  content: "Want to reach our readers? Contact us at persona@newsletter.com to advertise in our newsletter!"
};

const matchingAd = isPremium ? null : (allAds.find(ad => {
  const adTopics = ad.target_topics.toLowerCase().split(',').map(t => t.trim());
  return adTopics.some(topic => userTopics.includes(topic));
}) || defaultAd);

return [{
  json: {
    username: user.username,
    email: user.email,
    newsletter_style: user.newsletter_style,
    is_premium: isPremium,
    topics: user.topics,
    news: JSON.stringify(cleanNews),
    ad: matchingAd ? JSON.stringify(matchingAd) : null
  }
}];

const data = $input.first().json;
const previousData = $('Preprocessing').first().json;

// Get LLM output
const rawText = data.text || data.output || data.response || '';
const cleanText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
const jsonMatch = cleanText.match(/\[[\s\S]*\]/);
if (!jsonMatch) {
  throw new Error('No JSON array found: ' + cleanText.substring(0, 200));
}
const articles = JSON.parse(jsonMatch[0]);

// Get other data from preprocess node
const ad = previousData.ad ? (typeof previousData.ad === 'string' ? JSON.parse(previousData.ad) : previousData.ad) : null;
const username = previousData.username;
const email = previousData.email;
const isPremium = previousData.is_premium === 'true';
const date = new Date().toLocaleDateString('en-GB');

// Build articles HTML
const articlesHTML = articles.map((article) => `
  <div style="margin-bottom: 24px; padding: 16px; background: #f9f9f9; border-left: 4px solid #0047FF; border-radius: 4px;">
    <h2 style="margin: 0 0 8px 0; font-size: 16px; color: #1a1a1a;">
      <a href="${article.link}" style="color: #0047FF; text-decoration: none;">${article.title}</a>
    </h2>
    <p style="margin: 0; font-size: 14px; color: #444; line-height: 1.5;">${article.summary}</p>
  </div>
`).join('');

// Build ad HTML
const adHTML = ad ? `
  <div style="margin: 24px 0; padding: 16px; background: #fff8e1; border: 1px solid #ffd54f; border-radius: 4px;">
    <p style="margin: 0 0 4px 0; font-size: 11px; color: #888; text-transform: uppercase;">Sponsored</p>
    <p style="margin: 0; font-size: 14px; color: #444;">${ad.content}</p>
  </div>
` : '';

// Build full HTML
const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
</head>
<body style="margin: 0; padding: 0; background: #f0f0f0; font-family: Arial, sans-serif;">
  <div style="max-width: 600px; margin: 0 auto; background: white;">

    <!-- HEADER -->
    <div style="background: #0047FF; padding: 32px; text-align: center;">
      <h1 style="margin: 0; color: white; font-size: 28px; letter-spacing: 2px;">PERSONA</h1>
      <p style="margin: 8px 0 0 0; color: rgba(255,255,255,0.8); font-size: 14px;">Your personalized newsletter</p>
    </div>

    <!-- DATE + GREETING -->
    <div style="padding: 24px 32px 0 32px;">
      <p style="color: #888; font-size: 13px; margin: 0;">${date}</p>
      <h2 style="margin: 8px 0 24px 0; font-size: 20px; color: #1a1a1a;">Hello ${username} 👋</h2>
      <p style="margin: 0 0 24px 0; color: #444; font-size: 14px;">Here are your top ${articles.length} stories for today.
      </p>
    </div>

    <!-- ARTICLES -->
    <div style="padding: 0 32px;">
      ${articlesHTML}
    </div>

    <!-- AD -->
    <div style="padding: 0 32px;">
      ${adHTML}
    </div>

    <!-- FOOTER -->
    <div style="background: #1a1a1a; padding: 24px 32px; margin-top: 32px; text-align: center;">
      <p style="margin: 0 0 8px 0; color: #888; font-size: 12px;">You are receiving this because you subscribed to Persona.</p>
      <p style="margin: 0; color: #888; font-size: 12px;">© Persona 2026</p>
    </div>

  </div>
</body>
</html>
`;

return [{ json: { html, to: email, username } }];
